"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["39480"],{21218(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.importacao_externa_sem_banca_de_importacao_de_candidatos","status":422,"titulo":"O processo que importa candidatos de fora n\xe3o prev\xea a banca de importa\xe7\xe3o de candidatos"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.importacao_externa_sem_banca_de_importacao_de_candidatos","requisitos":["UNI-REQ-0339","UNI-REQ-0340"],"oQueAconteceu":["O processo importa candidatos de fora, como o SISU, e nenhuma fase nem etapa\\nprev\xea a banca de importa\xe7\xe3o de candidatos (UNI-REQ-0340). \xc9 essa banca que\\nimporta o arquivo de candidatos e resolve as cr\xedticas da importa\xe7\xe3o\\n(UNI-REQ-0339), no per\xedodo da fase de inscri\xe7\xe3o (UNI-REQ-0341). Sem ela, o\\narquivo n\xe3o teria quem o importasse, e o edital n\xe3o \xe9 publicado.","A banca \xe9 reconhecida pelo papel de importar candidatos, registrado na banca\\nquando ela \xe9 criada, e n\xe3o pelo nome do tipo. Qualquer que seja o uso da nota do\\nENEM, a importa\xe7\xe3o de fora exige esta banca.","A confer\xeancia \xe9 de completude e roda na publica\xe7\xe3o e na retifica\xe7\xe3o em ato\\n\xfanico. A recusa vem como o c\xf3digo desta p\xe1gina no corpo da resposta, e n\xe3o na\\nlista `errors[]`, e aponta o campo `fases` do processo, sem \xedndice."],"comoResolver":["Acrescente a banca de importa\xe7\xe3o de candidatos onde os candidatos s\xe3o\\nimportados, na fase ou na etapa. Essa banca importa; n\xe3o avalia nem julga\\nrecurso.","Exemplo: o \\"SISU 2027\\" s\xf3 \xe9 publicado com a fase de homologa\xe7\xe3o das inscri\xe7\xf5es,\\na banca de homologa\xe7\xe3o das inscri\xe7\xf5es\\n([banca ausente](/erros/uniplus.selecao.processo_seletivo.homologacao_das_inscricoes_sem_banca))\\ne a banca de importa\xe7\xe3o de candidatos.","O painel de conformidade aponta a pend\xeancia antes da publica\xe7\xe3o, no item\\n`cronograma_importacao_externa_com_banca_de_importacao_de_candidatos`."],"ondeAparece":["- Publica\xe7\xe3o inicial do processo seletivo\\n- Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);